    effect(() => {
      this.session.sheetId();
      this.session.loads();
      this.made.set(null);
      this.error.set(null);
    });
  }

  protected async generate(): Promise<void> {
    if (this.busy()) return;
    this.made.set(null);
    this.error.set(null);
